previewCss:
.darma-loader-darma-b8-helix-ribbon { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 80px); height: calc(var(--loader-size, 80px) * .6); display: flex; align-items: center; justify-content: space-between; perspective: 500px; }
.darma-loader-darma-b8-helix-ribbon span { width: 10%; height: 100%; background: linear-gradient(var(--accent), var(--accent-2)); border-radius: calc(var(--loader-size, 80px) * .03); animation: darma-loader-darma-b8-helix-ribbon-twist calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b8-helix-ribbon span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b8-helix-ribbon span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b8-helix-ribbon span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b8-helix-ribbon span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b8-helix-ribbon span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b8-helix-ribbon span:nth-child(6) { animation-delay: calc(var(--loader-speed, 1s) * .5); }
@keyframes darma-loader-darma-b8-helix-ribbon-twist { 0%, 100% { transform: rotateY(0deg) scaleY(.4); } 50% { transform: rotateY(180deg) scaleY(1); } }

